src='''import collections

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    background = collections.Counter(v for row in out for v in row).most_common(1)[0][0]
    seen = set()

    for r in range(h):
        for c in range(w):
            color = out[r][c]
            if color == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and out[yy][xx] == color:
                        seen.add((yy, xx))
                        stack.append((yy, xx))

            r0 = min(y for y, _ in component)
            r1 = max(y for y, _ in component)
            c0 = min(x for _, x in component)
            c1 = max(x for _, x in component)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            perimeter = {
                (y, x)
                for y in range(r0, r1 + 1)
                for x in range(c0, c1 + 1)
                if y in (r0, r1) or x in (c0, c1)
            }
            if set(component) != perimeter:
                continue
            if not all(out[y][x] == background for y in range(r0 + 1, r1) for x in range(c0 + 1, c1)):
                continue

            inner_h, inner_w = r1 - r0 - 1, c1 - c0 - 1
            fill = 2 if inner_h % 2 == 0 and inner_w % 2 == 0 else 7
            for y in range(r0 + 1, r1):
                for x in range(c0 + 1, c1):
                    out[y][x] = fill
    return out
'''
